    private fun sig(r: ParseResult): String = when (r) {
        is ParseResult.Transaction -> "T/" + r.txn.type + "/" + r.txn.cardType + "/" + r.txn.cardLast4 + "/" + r.txn.amount + "/" + r.txn.merchant.take(18) + "/" + (if (r.ruleId.startsWith("pack:")) "PACK" else if (r.txn.auto) "auto" else "rule")
        is ParseResult.Statement -> "S/" + r.statement.cardLast4 + "/" + r.statement.statementBalance + "/" + (if (r.ruleId.startsWith("pack:")) "PACK" else "rule")
        is ParseResult.Ignored -> "IGN/" + r.reason.take(26)
        is ParseResult.Failed -> "FAIL"
        ParseResult.NotBank -> "NOTBANK"
    }
    private fun run(bank: String, text: String): String = try { sig(SmsParser.parseAsBank(bank, text, received, zone)) } catch (e: Throwable) { "EXC" }

    private fun audit(bank: String) {
        SmsParser.setMonthFirstDates(false)
        RulesPack.apply(null)
        val off = auditCorpus.map { run(bank, it.second.replace("\\n", "\n")) }
        val out = RulesPack.parse(auditPack, 3)
        check(out is RulesPack.Outcome.Ok) { "pack rejected: $out" }
        RulesPack.apply((out as RulesPack.Outcome.Ok).pack)
        val on = auditCorpus.map { run(bank, it.second.replace("\\n", "\n")) }
        RulesPack.apply(null)
        var hijack = 0; var hide = 0; var unignore = 0; var fresh = 0; var same = 0
        val lines = StringBuilder()
        for (i in auditCorpus.indices) {
            val a = off[i]; val b = on[i]
            if (a == b) { same++; continue }
            val tag = when {
                (a.startsWith("T/") || a.startsWith("S/")) && b.startsWith("IGN") -> { hide++; "HIDE" }
                (a.startsWith("T/") || a.startsWith("S/")) && (b.startsWith("T/") || b.startsWith("S/")) -> { hijack++; "CHANGED" }
                a.startsWith("IGN") && (b.startsWith("T/") || b.startsWith("S/")) -> { unignore++; "UNIGNORE" }
                else -> { fresh++; "NEW" }
            }
            if (tag == "NEW" && !b.endsWith("/PACK")) continue
            lines.append(tag).append('|').append(i).append('|').append(auditCorpus[i].first).append('|').append(a).append(" => ").append(b).append('|').append(auditCorpus[i].second.take(60)).append('\n')
        }
        fail("BANK=" + bank + " n=" + auditCorpus.size + " same=" + same + " HIDE=" + hide + " CHANGED=" + hijack + " UNIGNORE=" + unignore + " NEW=" + fresh + "\n" + lines)
    }

    @Test fun audit00() = audit("Mashreq")
    @Test fun audit01() = audit("HDFC Bank")
    @Test fun audit02() = audit("Emirates NBD")
    @Test fun audit03() = audit("Liv")
    @Test fun audit04() = audit("ADIB")
    @Test fun audit05() = audit("Sharjah Islamic Bank")
    @Test fun audit06() = audit("CBD")
    @Test fun audit07() = audit("ADCB")
    @Test fun audit08() = audit("FAB")
    @Test fun audit09() = audit("Other bank")
}
